window.HARDTRP.receive("269933",[[269934,"2026-10-13T14:51:21",9,"Начало темы.\n\n@Pit_d12 — Дм этой темы.",269933,null],[270004,"2026-10-13T17:22:19",59,"@iakukot @HKS_Roar_Greninja_dnd как вы готовы?",269933,null],[270006,"2026-10-13T17:23:09",24,"Да/",269933,null],[270007,"2026-10-13T17:23:36",59,"/лист персонажа ссылка",270006,null],[270008,"2026-10-13T17:24:08",59,"/про дефф не забываем",269933,null],[270009,"2026-10-13T17:24:30",24,"Герсон Бум \n\nhttps://t.me/c/3239766844/6031/6034\n\n//",269933,null],[270012,"2026-10-13T17:25:38",59,"//да 1 лвл у тебя почти ничего нету, чтобы дать дефф",270009,null],[270013,"2026-10-13T17:25:47",59,"/может, ты хочешь на 3 level сразу?",270009,null],[270014,"2026-10-13T17:25:49",58,"//да",270004,null],[270015,"2026-10-13T17:26:58",58,"// https://t.me/c/3239766844/1725 анкета мага",269933,null],[270018,"2026-10-13T17:27:21",24,"Не, как рисковать так рисковать)/",270013,null],[270019,"2026-10-13T17:27:39",59,"/ладно",269933,null],[270021,"2026-10-13T17:28:52",59,"*\nВы отряд   только что подписал контракт на выполнение задания, от которого у любого нормального авантюриста случился бы нервный тик. Выходя из гильдии, они услышали странный гул. Он нарастал, как будто где-то вдалеке умирал дракон, но при этом его душили подушкой.\n\nОбернувшись, они увидели это.\n\nПо улице, снося лотки торговцев, петухов и чью-то бабушку с пирожками, несся РОЗОВЫЙ ЖЕЛЕЗНАЯ КАРЕТА БЕЗ ЛОШАДЕЙ, ВЫШЕДШАЯ ЛИБО С КРУГОВ АВЕРНУСА, ЛИБО МЕХАНУСА. Не просто розовый. А розовый, как кошмар барби-маньяка после трёх суток без сна. Из выхлопной трубы валил дым цвета жевательной резинки, а музыка из окон орала так, что у эльфа в отряде пошли уши в трубочку.\n\nНо это было только начало.\n\nЗа рулём сидел СКЕЛЕТ. Обычный такой скелет. Но с ГОРЯЩИМИ ЗЕЛЁНЫМИ ГЛАЗАМИ, которые светились ярче, чем магический кристалл в заднице у архимага. На черепе у него была повязана РОЗОВАЯ БАНДАНА с нарисованными ПОНИ. Да, с пони. И эти пони смотрели на мир с таким же безумным выражением, как и сам водитель.\n\nНа номере грузовика красовалось: «Ли 018».\n\nСкелет высунул костлявую руку в окно, показал символ мира\n\n— КАКОГО ХРЕНА?! — заорал кто-то\n\n\n\n— Я НЕ ПОДПИСЫВАЛСЯ НА ЭТО! — визжал кто-то из вас\n\nСкелет высунулся в окно, поправил бандану и крикнул:\n\n— ПОДВИНЬТЕСЬ, ЛОХИ! ВЫ ЕДЕТЕ В ДРУГОЙ МИР!",269933,null],[270022,"2026-10-13T17:29:01",58,"//блять мне страшно уже",270018,null],[270023,"2026-10-13T17:29:26",58,"//щяс до дома дойду и буду играть извиняюсь",269933,null],[270024,"2026-10-13T17:30:34",24,"*Герсон смеется*",269933,null],[270025,"2026-10-13T17:31:38",59,"/жду первого начальный реакции персов*",269933,null],[270028,"2026-10-13T17:32:29",24,"*Герсон смеется*\n\n-Ой ой ой молодежь.....",269933,null],[270040,"2026-10-13T17:49:26",58,"михуил с разочированием вздохнул и сказал\n-че блять",270021,null],[270042,"2026-10-13T17:50:31",59,"/ну да, не все поймут Юмора понимаю/",269933,null],[270050,"2026-10-13T17:59:01",59,"* БАМ!\n\nЧто-то ударило их. Не кулак. Не молния. Не боевой молот дварфа-алкоголика. Это был удар реальности. Как будто сама вселенная сказала: «А не пошли бы вы куда подальше?» — и отвесила им такого леща, что душа вылетела через пятку.\n\nОтряд резко подскочил — все четверо одновременно, как марионетки, которых дёрнул за верёвочки контуженный кукловод. Глаза распахнулись. Лёгкие схватили воздух Они оказались не там.\n\nСовсем не там.\n\nВокруг — ничего привычного. Ни гильдии. Ни улицы. Ни того розового грузовика, который, к слову, тоже куда-то делся. Вместо этого — место. Странное. Непонятное. Оно переливалось, дышало, пульсировало \nЗапах. Первое, что ударило в нос — жжёная карамель, смешанная с озоном после грозы и мокрым мехом. Как будто кто-то поджарил сладкое на молнии, а потом обмакнул это в шерсть мокрой собаки Вкус. Во рту — металл. Как будто они только что лизнули наковальню. \nА потом — сладость. Приторная, как будто кто-то залил им в глотку литр мёда, пока они были в отключке.*",269933,null],[270054,"2026-10-13T18:00:47",24,"Герсон: -Вот что нынче происходит. Хеех",269933,null],[270063,"2026-10-13T18:07:26",58,"*михуилд сжал посох в руках проверил книгу за рубашечкой решал взять ножик левой рукой и сказал \n-блять",270050,null],[270064,"2026-10-13T18:10:04",59,"*Обратите внимание на место, где он находится.\nОн восседает на троне, выполненном из чёрного дерева и красного бархата, с непринуждённо закинутыми ногами. Его взгляд направлен на недавно появившихся попаданцев с лёгкой заинтересованностью, словно кот на утреннюю газету — без всякого намерения вставать.\n\nЕго шесть глаз моргают не одновременно, словно каждый из них живёт своей жизнью.*\n–НУ ЧТО, МОИ РАБОТНИКИ НА ПОЛСТАВКИ , ДОБРО ПОЖАЛОВАТЬ В ЖОПУ МИРОЗДАНИЯ! ШУТКА В МОЕМ СКРОМНОМ ЖИЛИЩЕ",269933,null],[270065,"2026-10-13T18:11:40",58,"*михуил посмотрев на него *\nне в обиду тебе но у меня вопрос а в какую пару глаз тебе смотреть?",269933,null],[270066,"2026-10-13T18:12:21",59,"*Фиолетовый смотрит в прошлое. Зелёный — в будущее. Жёлтый — в буфет. Красный — оценивает угрозу. Синий — просто красивый. А шестой, который на лбу, обычно закрыт.*",269933,null],[270067,"2026-10-13T18:13:11",58,"//а что в буфете на ужин?",270066,null],[270068,"2026-10-13T18:15:19",24,"Герсон: -Так что вам нужно от нас. Мистер много глаз. Совет от мудрой черепахи?",269933,null],[270071,"2026-10-13T18:17:43",59,"— Итак, слушайте внимательно, смертные! — Его голос, одновременно бархатистый и резкий, словно скрежет сковородки, разносится по округе. «У меня есть знакомый, — говорит он. — И у него есть для вас небольшое поручение. Готовы ли вы взяться за это дело и получить награду от меня, великого?»",269933,null],[270073,"2026-10-13T18:18:09",24,"-Я не против",269933,null],[270080,"2026-10-13T18:21:28",59,"– А что скажешь ты, смертная девочка, похожая на мальчика?",269933,null],[270082,"2026-10-13T18:22:09",58,"-наоборот",270080,null],[270083,"2026-10-13T18:23:49",59,"*Отуран  Волдырин откидывается на спинку трона и прикрывает пять глаз из шести. Шестой, на лбу, лениво приоткрывается, смотрит на отряд*",269933,null],[270086,"2026-10-13T18:32:00",58,"-хм а нахуй мы тут нужны кста?",270083,null],[270087,"2026-10-13T18:33:52",59,"– Я уже упоминал, что вы работник на полставки вместо меня будете вкалывать",269933,null],[270089,"2026-10-13T18:34:12",58,"-а отказ принимается?",270087,null],[270090,"2026-10-13T18:34:49",59,"–Сейчас да, а потом.......",270089,null],[270091,"2026-10-13T18:36:01",58,"-такой вопрос есть а не логичнее было сначало спросить а потом пиздить нас с улицы наркоманов?",269933,null],[270092,"2026-10-13T18:37:27",59,"— Вы согласились на собеседование и классический способ доставки. Необходимо было уточнить, какой именно классический способ имеется в виду.\n😁😏",270091,null],[270093,"2026-10-13T18:38:54",59,"–у каждого существа разное восприятия",269933,null],[270094,"2026-10-13T18:39:24",58,"-ладно всеравно нехуй днлать я за",269933,null],[270095,"2026-10-13T18:40:33",59,"*видимо не дождавшись ничего большего вопросов \nПадает на вас луч света*",269933,null],[270096,"2026-10-13T18:40:39",59,"Не просто луч. А ЛУЧ. Ослепительно-белый, с розовыми и фиолетовыми искрами, он врезался в пол прямо перед отрядом, расплескался во все стороны, как вода из опрокинутого ведра, и заставил всех четверых зажмуриться.\n\nА когда они открыли глаза...\n\nПод их ногами уже рисовалась пентаграмма.\n\nНе просто пентаграмма. А ПЕНТАГРАММА. С большой буквы. Огромная. Светящаяся.",269933,null],[270100,"2026-10-13T18:41:38",24,"*Герсон посмотрел в низ*\n\n-Мистика мистика.",269933,null],[270101,"2026-10-13T18:41:38",58,"-блять ну я же не некромант",269933,null],[270113,"2026-10-13T18:50:21",59,"*Выйдя из яркого света, ПЕНТАГРАММА оказалась в новом месте. Перед ними предстали гоблины. Девять маленьких, зелёных, сморщенных и кривоногих существ в потрёпанных одеждах. Их тряпьё выглядело так, словно его долго жевали, а затем вернули гоблинам. Штаны были рваными, рубашки — в дырах. Те, у кого была обувь, стояли в ней, а те, кто её не имел, стояли босиком, и, судя по их лицам, не жаловались на это.\n\nГоблины стояли полукругом, молча глядя на игроков. Их жёлтые глаза блестели в полумраке, длинные носы подрагивали, а острые уши дёргались. Они ждали. Перед ними, чуть впереди, крутился шаман.\n\nОн был стар. Очень стар. Его зелёная кожа местами посерела, а морщины пересекали лицо так часто, что казалось, будто кто-то резал его ножом. Его одежда была хуже, чем у остальных — балахон из мешковины, украшенный костями (чьими — лучше не спрашивать), перьями (какими — лучше не думать) и бусинами (откуда — лучше не знать). В одной руке он держал посох — кривой, облезлый, увенчанный черепом какого-то мелкого зверька. Череп светился слабым зелёным светом. Или это были глаза шамана — уже не разобрать.*",269933,null],[270114,"2026-10-13T18:51:18",24,"*Герсон смотрит*",269933,null],[270116,"2026-10-13T18:52:16",59,"*Он кружился вокруг своей оси. Медленно. С восторгом. Бормоча что-то себе под нос. Иногда подпрыгивая, иногда вскидывая посох, а иногда кланяясь так низко, что его нос почти касался земли.*\n\n— О-о-о-о, — тянул он. — Пришли.... Пришли.... Пришли. Пришли... (Кашлять)\nВел...икие чуж....аки.",269933,null],[270118,"2026-10-13T18:54:57",58,"-привет маленький ты кто такой?",269933,null],[270119,"2026-10-13T18:56:37",59,"Шаман остановился. Уставился на вас. Его глаза горели зелёным. Посох задрожал в руке. Череп на конце открыл рот (хотя не должен был) и издал звук, похожий на смех и плач одновременно.\n\n— Вы... — прошамкал он, тыкая в вас костлявым пальцем. — Вы... те самые... которых... звали...",269933,null],[270126,"2026-10-13T19:01:03",58,"-тип того",269933,null],[270132,"2026-10-13T19:15:41",59,"Шаман (старый, восхищённый, говорливый, то и дело покашливает, хрипит, делает паузы, будто собирается с силами):\n\n— О-о-о... кх-кх... Великие чужаки! Великие! Пришли!.. Пришли к нам!.. кх Я знал! Я говорил!.. Я всем говорил: «Придут!.. Придут великие чужаки!» И вот... кхе-кхе... пришли...\n\nСмотрите, сородичи!.. Смотрите на них!.. Кожа!.. Одежда!.. Обувь!.. кх У них есть обувь!.. На обоих ногах!.. Это знак!.. Это великий знак!..\n\nСлушайте... слушайте, великие чужаки... кх-кх... Давно... очень давно... когда я был ещё молодым гоблином... а это было... о-о-о... очень давно... кхе... наше племя жило у Большой Воды...\n\nРыба!.. кх Много рыбы!.. Жирной!.. Вкусной!.. Но потом... пауза, кашель... потом пришли злые люди... Большие люди... С палками... С огнём... кх-кх... Они прогнали нас... Забрали воду... Забрали рыбу...\n\nИ мы ушли... тяжёлый вздох, кашель... Ушли в лес... В тёмный лес... Где нет рыбы... Где нет воды... Где только корни... И жуки... И страх...\n\nО-о-о, великие чужаки... кх... помогите нам!.. Помогите племени!.. Мы слабые... Мы маленькие... Мы... (Закашлялся, махнул рукой...) мы...",269933,null],[270133,"2026-10-13T19:16:40",59,"Грыз (коренастый, бьёт кулаком в ладонь):\n— Хватит орать, старик. Дело есть. Дело. Бить надо. Бить. Людей бить. Палки ломать. Огонь тушить. Вот. Всё. Просто. Бить.\n\nШаман (машет посохом):\n— Нет! Нет! Не просто! Не просто! Слушать надо! Слушать! Я старый! Я знаю! Давно... давно... вода была. Рыба была. Много. Потом — нет. Люди пришли. Палки. Огонь. Прогнали. Мы ушли. Лес. Корни. Жуки. Плохо. О-о-о. Плохо.\n\nШныг (тощий, дёргается, пискляво):\n— А-а-а! Не надо бить! Не надо! Страшно! Кровь! Красная! Липкая! А-а-а!",269933,null],[270135,"2026-10-13T19:20:42",58,"-... я правельно понимаю что вы хотите чтобы мы отпинали тех людей и вы могл бы жить у воды да?",269933,null],[270136,"2026-10-13T19:22:06",59,"Жуй (толстый, жуёт, равнодушно):\n— М-м-м. Кровь? Еда? Еда есть? Нет? Ну и ладно. Жую корень. Всё равно.\n\nСкак (молодой, подпрыгивает):\n— Бить! Бить! Я хочу! Слава! Песни! Прыгать! Бежать! Вперёд! Да! Да!",269933,null],[270137,"2026-10-13T19:22:14",59,"Шаман (стучит посохом по земле):\n— Тихо! Тихо! Слушать! Слушать меня! Чужие! Великие! Помогите! Племя маленькое! Гоблины слабые! Мы — слабые! Да! Помогите! Пожалуйста! О-о-о!\n\nГрыз (перебивает):\n— Не проси. Не надо. Бить надо. Бить. Я — Грыз. Кулак. Вот. (показывает кулак) Бить. Всё. Хватит слов.",269933,null],[270138,"2026-10-13T19:23:24",59,"Глаз (смотрит на вас):\n— Чужие. Молчат. Смотрят. Думают. Может. Может — умные. Может — нет. Но молчат. Это... это хорошо. Да. Хорошо.\n\nШаман (кивает, восхищённо):\n— Да! Да! Глаз прав! Глаз всегда прав! Чужие молчат! Слушают! Хорошо! Хорошо! О-о-о! Великие чужие! Скажите! Скажите что-нибудь! Что делать? Бить? Не бить? Помочь? Не помочь? О-о-о!\n\nГрыз (скрестит руки):\n— Да. Говорите. Или я бью. Всё равно кого. Вас. Или людей. Или Скака. Всё равно.\n\nСкак (возмущённо):\n— Меня?! За что?!\n\nГрыз (пожимает плечами):\n— Прыгаешь много.",269933,null],[270139,"2026-10-13T19:25:19",59,"Шаман (поднимает посох, череп светится):\n— О-о-о! Чуж...ие! Великие! Слу...шайте! Слуша...йте! Плем....я ждёт! Ждёт! Скаж..ите! Скажите слово! Одно сл...ово! Пожалуйста! О-о-о!\n\nГоблинята (из-за спин, шёпотом):\n— Хи-хи. Слово. Слово. Хи-хи.🙃\n\nВсе замолкают. Девять пар жёлтых глаз смотрят. Шаман стоит с открытым ртом. Грыз сжимает кулаки. Шныг дрожит. Жуй жуёт. Скак сидит надутый. Глаз молчит. Гоблинята хихикают.",269933,null],[270140,"2026-10-13T19:32:40",58,"-это кто такие? \n*спросил михуил нихуя не понимая что происходит",269933,null],[270141,"2026-10-13T19:33:29",24,"*Герсон немного уснул стоя. Все же пожилой уже. Но потом проснулся*\n\n-Так ребята. Что я  пропустил?",269933,null],[270142,"2026-10-13T19:33:29",59,"/шаман говорит про прошлое история  племёный и вы далеко от этого места/",270140,null],[270143,"2026-10-13T19:34:42",58,"//не догоняю",270142,null],[270144,"2026-10-13T19:35:39",59,"//Шаман начал рассказывать историю племени потом подключились другие показав свои характеры это пока что*",270143,null],[270145,"2026-10-13T19:35:46",59,"!!!!!!!!!!!!!!!!!!!!!!!!!",269933,null],[270146,"2026-10-13T19:36:00",58,"//ну я и у этох кто пришел спрашиваю кто они",269933,null],[270147,"2026-10-13T19:36:49",59,"/ну, тогда подожди пару минут надо составить красиво текст  попробую*",270146,null],[270148,"2026-10-13T19:37:47",58,"//что то пошло не поплану ( я тут еще курсовую пишу так что б на англиском слючайно писать буду)",269933,null],[270149,"2026-10-13T19:42:04",59,"Шаман (замирает, смотрит вдаль, потом резко поворачивается — и сразу кашляет, сгибаясь):\n— Кха! Кха-кха! Ох... Люди? Люди! Да! Да! Люди! О-о-о! Это давно! Давно! Очень... кха!.. давно! Я был маленький! Вот такой! (пытается показать рукой у колена, но рука дрожит, и он хватается за поясницу) Ох... спина... старая спина... Да! Маленький! Совсем маленький! Мы жили там! (машет посохом куда-то, но посох чуть не падает, он его ловит) У воды! Большой воды! Много воды! Рыба! Много рыбы! Жирная! Вкусная! Мы ели! Ели! Потом — кха-кха! — бам! Люди! Большие! С палками! С огнём! Прогнали! Мы бежали! Бежали! Долго! Пришли сюда! Лес! Тёмный! Корни! Жуки! Плохо! О-о-о! Плохо! (кашляет снова, вытирает рот ладонью) Ох...\n\nИгрок (пытается уточнить):\n\nШаман (не слушает, но теперь говорит тише, с паузами, как будто вспоминает через силу):\n— А помню... помню... кха... был день. Солнце. Большое. Жёлтое. Я поймал рыбу. Вот такую. (разводит руки, но они дрожат, и он их опускает) Нет... не такую. Меньше. Или больше. Не помню. Но большая. Да. А потом... потом... ох, ноги... старые ноги... я упал. В воду. Плюх. Мокрый. Холодно. О-о-о. А мать... мать... (замолкает, смотрит в землю) ...как её звали? Не помню. Она кричала. А я... я... не помню. Но кричала. Да. (поднимает голову, пытается улыбнуться, но улыбка выходит кривой) Я тогда... я тогда... уже был шаманом? Нет. Не был. Но хотел. Да. Хотел. Кха!",269933,null],[270150,"2026-10-13T19:44:02",59,"Грыз (бьёт кулаком в ладонь, рычит):\n— Хватит! Хватит про рыбу! Про мать! Про воду! Надоело! Люди! Спрашивают про людей! Говори про людей! Не про рыбу!\n\nШаман (обиженно, выпрямляется, насколько может, тычет посохом в Грыза — но посох дрожит):\n— Не перебивай! Не перебивай старика! Я... я помню! Я всё помню! Я шаман! Я... кха!.. я много помню! Люди... люди... были... большие! Да! Большие! Высокие! Вот такие! (тянется вверх, но спина хрустит, и он сгибается обратно) Ох... Выше меня! Выше Грыза! Выше... кха... всех! И... и... у них были... были... (задумывается, чешет затылок, потом смотрит на свои руки) ...палки! Да! Палки! И огонь! Огонь! Он... он... горел! Да! Горел! И... и... ещё... (замолкает, кашляет, смотрит в небо) ...а помню, небо было... синее? Или зелёное? Не помню. Но было. Да. Красивое. Наверное. Кха.",269933,null],[270151,"2026-10-13T19:46:49",58,"-а давайте ближе к сути теперь что от нас требуется?",269933,null],[270152,"2026-10-13T19:47:06",59,"Грыз (бьёт кулаком в ладонь, рычит):\n— Хватит! Хватит про рыбу! Про мать! Про воду! Надоело! Люди! Спрашивают про людей! Говори про людей! Не про рыбу!\n\nШаман (обиженно, выпрямляется, насколько может, тычет посохом в Грыза — но посох дрожит):\n— Не перебивай! Не перебивай старика! Я... я помню! Я всё помню! Я шаман! Я... кха!.. я много помню! Люди... люди... были... большие! Да! Большие! Высокие! Вот такие! (тянется вверх, но спина хрустит, и он сгибается обратно) Ох... Выше меня! Выше Грыза! Выше... кха... всех! И... и... у них были... были... (задумывается, чешет затылок, потом смотрит на свои руки) ...палки! Да! Палки! И огонь! Огонь! Он... он... горел! Да! Горел! И... и... ещё... (замолкает, кашляет, смотрит в небо) ...а помню, небо было... синее? Или зелёное? Не помню. Но было. Да. Красивое. Наверное. Кха.\nШныг (дёргается, машет руками):\n— А-а-а! Он опять! Опять не то! А-а-а! Спросили про людей! А он про небо! А-а-а!\n\nЖуй (жуёт, равнодушно):\n— М-м-м. Небо. Синее. Или зелёное. Всё равно. Жую.\n\nСкак (подпрыгивает):\n— Я знаю! Я знаю про людей! Они большие! Они злые! Они... они... (задумывается) ...они большие! Да! И злые! И... и... я хочу их бить! Да! Бить!\n\nГлаз (тихо, не поднимая головы):\n— ...Ты. Мелкий. Ничего. Не знаешь.",269933,null],[270153,"2026-10-13T19:50:41",59,"Шаман (медленно, с паузами, опираясь на посох, кашляет в кулак):\n— Кха... кха-кха... О... великие чужие... вы... вы слушали... долго... спасибо... кха... а теперь... теперь... ближе... да... ближе к делу... дело... дело такое... кха... помогите... помогите выжить... нашему племени... да... выжить... и... и... развиться... кха-кха... вот... вот и всё... пока... пока всё... больше... больше ничего... кха... не скажу... пока... не могу... сил... сил мало... кха...",270151,null],[270154,"2026-10-13T19:51:43",58,"-а как имено помочь типо найти новое место для вас или помоч вернуть старое?",269933,null],[270155,"2026-10-13T19:54:40",59,"/Откровенно говоря, у вас сложная задача. Нужно помочь племени развиваться, обеспечить его выживание и решить множество других важных вопросов. Это нелёгкий квест, в котором предстоит учесть множество нюансов/.",270154,null],[270157,"2026-10-13T19:55:35",58,"//тобишь этот квест как каканибудь идти игра да?",270155,null],[270158,"2026-10-13T19:55:40",24,"Герсон: -Думаю я смогу помочь",269933,null],[270160,"2026-10-13T19:57:00",59,"Приспешник Гоблин (9 штук)\n\nМаленький? Гуманоид (Гоблиноид), нейтрально-злой\nКласс Доспеха 13 (Кожаная броня)\nХиты 7 (2к6)\nСкорость 30 футов\nСил\n8 (-1)\nЛов\n14 (+2)\nТел\n10 (+0)\nИнт\n10 (+0)\nМдр\n8 (-1)\nХар\n8 (-1)\nНавыки Скрытность +6\nЯзыки Гоблинский\nОпасность 1/8 \nБонус мастерства +2\nЛовкий побег. Гоблин может в каждом своем ходу бонусным действием совершать действие Засада или Отход.\nДействия\nДубинка. Рукопашная атака оружием: +1 к попаданию, досягаемость 5 футов, одна цель. Попадание: Дробящий 3 (1к4).",269933,null],[270161,"2026-10-13T19:58:01",58,"//теперь я понел почему дьвол сам не захотел идти",269933,null],[270162,"2026-10-13T19:58:46",58,"//ну го ты едой займешся а я защитой",269933,null],[270163,"2026-10-13T19:58:58",58,"//устраивает?",270162,null],[270164,"2026-10-13T19:59:41",24,"Герсон: -Так как поделим управление?",269933,null],[270165,"2026-10-13T20:00:48",58,"-ну чур я займусь защитой а ты тогда еду сможешь добыть?",269933,null],[270166,"2026-10-13T20:01:13",24,"-Неплохо молодой. Хорошая идея",269933,null],[270167,"2026-10-13T20:01:27",58,"-жилищя мне кажется в меньшем приоритете",269933,null],[270168,"2026-10-13T20:02:27",58,"//вопрос я могу использовать заклинания чисто как для интеректива и не тратить ячейки на постройку?",269933,null],[270169,"2026-10-13T20:02:44",24,"-Я ими тоже могу заняться",270167,null],[270170,"2026-10-13T20:03:33",58,"-щяс лючше еду тебе раздобыть а дом потом",270169,null],[270171,"2026-10-13T20:03:58",24,"*Герсон пошел искать еду*",269933,null],[270172,"2026-10-13T20:05:13",58,"//и яма щяс такой вы вместе должны все делать :3",269933,null],[270173,"2026-10-13T20:05:45",59,"Мальшый Гоблинов (6 штук)\n\nМаленький? Гуманоид (Гоблиноид), нейтрально-злой\nКласс Доспеха 10 \nХиты 4\nСкорость 25 футов\nСил\n8 (-1)\nЛов\n12 (+1)\nТел\n10 (+0)\nИнт\n8 (-1)\nМдр\n6 (-2)\nХар\n8 (-1)\nНавыки Скрытность +4\nЯзыки Гоблинский\nОпасность 0\nБонус мастерства +2\n\nДействия\nКамни +0 к попаданию, урон 1к4 радиус поражения 15 футов",269933,null],[270174,"2026-10-13T20:06:45",24,"Дети, учить будут/",270173,null],[270175,"2026-10-13T20:07:01",24,"Или они как в игре Family Time? Лучшая рабочая сила/",269933,null],[270176,"2026-10-13T20:09:55",58,"//я вспомнил что мне говорили про квест и кажись у меня пазл сложился",269933,null],[270177,"2026-10-13T20:10:13",59,"Шаман гоблинов \nМаленький? Гуманоид (Гоблиноид), нейтрально-злой\nКласс Доспеха 12\nХиты 11\nСкорость 30 футов\nСил\n8 (-1)\nЛов\n12 (+1)\nТел\n10 (+0)\nИнт\n11 (0)\nМдр\n12 (+1)\nХар\n8 (-1)\nНавыки Скрытность +4\nМагия +1\nЯзыки Гоблинский\n\nБонус мастерства +2\nДействия.\nНАСТУПЛЕНИЕ ТОТЕМОВ\nВы можете временно высвободить остатки энергии духов, заключенных в ваших тотемах, чтобы напасть на врагов. Пока вы держите один из своих тотемов, вы можете действием заставить одно существо, которое вы видите в радиусе 60 футов от себя, совершить спасбросок Харизмы. Если спасбросок провален, существо получает 1к8 урона некротической энергии. (2 раза)\n\nЗаговор:формирование воды.\nПосох +2 попадание урон 1к6",269933,null],[270182,"2026-10-13T20:12:04",58,"//вопрос у нас гоблины эти на бои от вол врагов которые на нас будут наступать?",269933,null],[270184,"2026-10-13T20:12:40",59,"//не они напарники помощники товарищи",270182,null],[270185,"2026-10-13T20:13:11",59,"/вы ими будете управлять во время битвы иногда, если будут слушать ваши приказы",269933,null],[270186,"2026-10-13T20:13:12",58,"//ну они наши напарники аротив врагов которыеибудут на нас наступать я имел в виду",270184,null],[270187,"2026-10-13T20:13:29",59,"// да насколько они будут вам, вас слушать",270186,null],[270188,"2026-10-13T20:15:03",58,"//ю",270168,null],[270189,"2026-10-13T20:18:34",59,"Не забывайте про важный момент \n0: кризис.\n\n1: плохо.\n\n2: терпимо.\n\n3: хорошо.\n\n4: очень хорошо.\n\n5: превосходно",270156,null],[270190,"2026-10-13T20:19:06",59,"/придётся потратить и отдохнуть.",270168,null],[270191,"2026-10-13T20:19:17",24,"*Герсон вернулся. Он хочет собрать небольшой отряд Гоблинов собирателей (3 особи) чтобы пойти собирать еду*",270156,null],[270193,"2026-10-13T20:19:22",58,"//жаль",270190,null],[270194,"2026-10-13T20:19:58",58,"//так тебе на еду нужны гоблены",269933,null],[270195,"2026-10-13T20:22:32",58,"//как будем пилить гобленов?",270194,null],[270196,"2026-10-13T20:22:33",59,"/может, более подробно опишешь, как это ты делаешь? И может, будешь кидать проверку на выступление, убеждение, запугивание./",270191,null],[270197,"2026-10-13T20:22:44",24,"Оке/",269933,null],[270198,"2026-10-13T20:23:14",24,"/r 1d20 выступление",269933,null],[270200,"2026-10-13T20:25:33",58,"*михуил выходит и говорит \n-мне нужно 6 гобленов приспешников и 2 гоблина малыша для постройки защиты чтобы потом уже с чутвом безлпасности можно было бы начать выстраивать инфраструктуру деревни так что кто пойдет со мною",269933,null],[270201,"2026-10-13T20:25:41",58,"/r +1",269933,null],[270203,"2026-10-13T20:25:50",58,"//и никто не пошел",270202,null],[270205,"2026-10-13T20:26:22",58,"//так по лучше",270204,null],[270206,"2026-10-13T20:27:42",59,"Ты произносишь речь. Три гоблина смотрят на тебя с разной степенью понимания.\n\nПервый — Грызл, мелкий, но с самым большим ухом. Он чешет затылок и говорит:\n\n«Ты много слов сказал. Красиво. Я почти поверил. Ладно, пойду еду искать. Но если ты врёшь — я не удивлюсь. Ты уж больно складно говоришь для того, кто сам ничего не несёт».\n\nВторой — Мок, тот, что всё время ковыряет в носу. Он пожимает плечами:«Ага. Слова — как у вождя. Только вождь потом ещё и дубиной машет. А ты? Ну ладно. Помогу. Но еду буду искать там, где ты не сказал. На всякий случай».",270198,null],[270207,"2026-10-13T20:28:02",24,"*Герсон вышел немного выше*\n\n-Уважаемые гоблины. Мне нужно 3 отборных юнца что помогут мне прокормить ваше поселение. Я понимаю что уважения и статуса у нас нет но мы обещаем что не будем експлоатировать ваш труд",270199,null],[270208,"2026-10-13T20:29:49",58,"-остальные будет просьба занятся улучшение жильичных условий \n//я могу попросить подержку У моего напарника? Чтобы кинуть с преимуществом?",269933,null],[270209,"2026-10-13T20:31:33",59,"Ты говоришь. Про строительство. Про помощь. Про то, что вместе — сильнее.\n\nТишина.\n\nПотом один взрослый,  зевает и говорит:\n\n«Ага. Ну. Понятно».\n\nИ возвращается к своему делу.\n\nВторой,  не отрываясь от стены:\n\n«Ты это... того. Скажи, когда надо. А то я не понял, чего надо-то».\n\nТретий,  коротко:\n\n«Строить. Ну да. Ладно».\n\nОстальные трое вообще не реагируют — один смотрит в потолок, двое о чём-то своём перешёптываются.\nА малыши оживились. Пик выпячивает грудь и важно повторяет за Михаилом, копируя интонацию:\n\n— Мне! Нужно! Шесть гоблинов! При-спеш-ни-ков! И два! Ма-лы-ша!\n\nПак подхватывает, путаясь:\n\n— Мне... нузно... шесть... гоб... при... и два... ма...\n\nПик тыкает в Михаила пальцем и говорит Паку:\n\n— Он так сказал. Смешно, да?\n Пак хихикает. Пик снова выпячивает грудь и повторяет последнюю фразу Михаила, но ещё глупее — с той же важной миной. Пак за ним. Оба прыскают.",270200,null],[270210,"2026-10-13T20:33:28",58,"//Если что игнорирую что они говорят",270208,null],[270211,"2026-10-13T20:33:56",59,"/тебе и так решили помочь 3 гоблинов* \n*после твоей речи 3 гоблина выступили вперёд и подошли к тебе*",270207,null],[270212,"2026-10-13T20:34:15",24,"Ну я хотел как-то отыграть свою речь/",270211,null],[270213,"2026-10-13T20:34:24",59,"Давай",270212,null],[270214,"2026-10-13T20:34:34",24,"Так вот и отыграл/",270207,null],[270215,"2026-10-13T20:34:38",59,"/я думал, ты не хочешь/",269933,null],[270217,"2026-10-13T20:34:57",24,"Ну я пытаюсь больше отыгрывать. И более многословно/",270215,null],[270218,"2026-10-13T20:36:21",59,"Все трое встают. Мок хлопает себя по коленям:\n\n«Пошли, юнцы отборные. Покажем этому “мы” , как еду добывать».\n\nОни уходят. Писк на прощание оборачивается и добавляет уже совсем тихо:\n\n«А вообще... он мне почти понравился. Почти».",270207,null],[270219,"2026-10-13T20:36:49",24,"*Герсон идет с ними*",269933,null],[270220,"2026-10-13T20:37:25",24,"Герсон: -Я не король, я лидер. Лидер не бросит свою команду как генерал не бросит своих солдат.\n\n*Герсон идет с ними*",269933,null],[270222,"2026-10-13T20:38:13",59,"*попрошу студию выживания.*",270220,null],[270223,"2026-10-13T20:38:54",58,"*михуил оглядывает местность и пытается придумать из чего можно в теории сделать защиту",269933,null],[270224,"2026-10-13T20:39:23",59,"*восприятие*",270223,null],[270225,"2026-10-13T20:40:00",24,"/r 1d20+3",270222,null],[270227,"2026-10-13T20:40:12",59,"//ещё пару минут игры и мне надо будет отойти задание сделать и спать скоро мне//",269933,null],[270228,"2026-10-13T20:40:29",24,"Пон/",269933,null],[270229,"2026-10-13T20:40:51",58,"/r",269933,null],[270231,"2026-10-13T20:45:05",59,"Выйдя из чистокола лагеря.\nТрава тяжёлая, мокрая, стекает по голеням. Каждый шаг — хлюп, и где-то под ногами чавкает не то грязь, не то старая листва, пережившая не одну зиму. Воздух густой, как парное молоко. Пахнет корой, грибницей и чем-то сладковато-гнилым — где-то рядом падаль, но старая, уже почти земля.\n\nГрызл идёт первым. Ухо дёргается на каждую птицу. \nМок плетётся сзади, шмыгает носом и иногда что-то жуёт — нашёл вчерашнюю кость, не признаётся.  семенит в середине, озирается, но молчит. Все трое мокрые до нитки. Но злые. Злые — значит живые.\nВот тут-то Герсон и замечает. Не сразу. Сначала — просто тень между стволами. Потом — движение. Потом — тишина. Слишком тихо. Птицы замолчали. Даже Мок перестал жевать.\n\nИз-за поваленного бука, поросшего мхом, выходит молодой олень. Не самец с рогами — годовалый, худой, с пятнами на боках, ещё не перелинял. Он стоит, повернув голову, и смотрит прямо на них. Ноги у него длинные, неуклюжие, как у подростка. Уши дёргаются. Он не боится. Пока.\n\nГрызл медленно поднимает руку. Не назад, не вперёд — просто вверх. Ладонь раскрыта. Стой.\n\n«Мясо», — шепчет Мок, и в голосе у него столько голода, что Писк вздрагивает.\n\n«Тише», — шипит Грызл. — «Он один. Молодой. Глупый. Смотри — не бежит. Ещё не понял, что мы — это смерть».",270226,null],[270232,"2026-10-13T20:46:27",24,"-Готовы ребята?",269933,null],[270234,"2026-10-13T20:48:25",59,"Первое, что он видит: старый бурелом. Три дерева упали друг на друга, образовав что-то вроде навеса. Кора отслоилась, но стволы ещё крепкие. Если подпереть — можно сделать стену. Ненадёжную, но стену. Гоблины не додумались. Или им лень.\nВторое: кости. Под слоем листвы, у самого края лагеря— старые кости. Не человеческие. Что-то крупное, оленье или кабанье. Уже обглоданные, сухие, серые. Но некоторые — длинные, прямые. Мок видел, но не тронул. Писк наступил и не заметил. Мухиал замечает. Он наклоняется, берёт одну. Кость тяжёлая. Прочная. Ей можно резать. Ей можно колоть. Ей можно забивать.\n\nТретий: ельник. Молодой, густой, с острыми ветками. Но среди них есть сухие. Мёртвые. Они не гнутся — ломаются с треском. Если наломать и связать — будет частокол. Низкий, но частокол. А ещё из них можно делать колья. Короткие, но острые.",270223,null],[270235,"2026-10-13T20:49:15",59,"–деа, мы вумный",270232,null],[270236,"2026-10-13T20:50:10",24,"-Нападайте на него с другой стороны. А я остановлю его попытку сбежать с этой стороны.",270235,null],[270237,"2026-10-13T20:51:09",59,"/r d20+6 на скрытность гоблина на выполнение тактики",269933,null],[270240,"2026-10-13T20:52:34",58,"-так гоблены пошлите щяс будет делать стены из вон тех теревьев и надо будет скептись это все между собою так что вы 6 и я идем тащит дерево а другие 2 будут скреплять все частоколами все поняли?",270234,null],[270241,"2026-10-13T20:53:41",59,"*Обойдя со всех сторон, вы ловко захватываете оленёнка в плен. Гоблины с удивлением отмечают, насколько просто вам это удалось.*",270236,null],[270242,"2026-10-13T20:54:19",59,"*Но внезапно оленёнок начинает отчаянно брыкаться и бежит, пытаясь прорваться сквозь строй.*",269933,null],[270244,"2026-10-13T20:54:26",24,"-Хорошая стратегия - больше половины сделанного дела. Стоп!",269933,null],[270245,"2026-10-13T20:54:46",24,"*Старый Тортл бежит к оленю и пытается его ударить молотом*",269933,null],[270246,"2026-10-13T20:55:04",24,"Я про Герсона/",270245,null],[270248,"2026-10-13T20:55:22",59,"/на попадание хоть и я хотел противостояние сделать ну ладно видимо ты раньше бьёшь его",270245,null],[270249,"2026-10-13T20:56:01",59,"/ну?",269933,null],[270250,"2026-10-13T20:56:08",24,"/r 1d20+6",269933,null],[270251,"2026-10-13T20:56:12",59,"/где на попадание",269933,null],[270254,"2026-10-13T20:57:44",59,"/ попал урон",269933,null],[270257,"2026-10-13T21:00:44",24,"/r 2d6+4",269933,null],[270261,"2026-10-13T21:01:24",59,"*мощным ударом. черепашка разломила наполовину оленёнка*",269933,null],[270262,"2026-10-13T21:02:21",24,"-Будет проще нести/",269933,null],[270263,"2026-10-13T21:02:29",24,"Располовинить молотом/",270261,null],[270265,"2026-10-13T21:02:32",24,"?/",269933,null],[270266,"2026-10-13T21:03:05",59,"/короче, я все если не сложно, можно оценочку в обсуждении про начало конечно, знаю, что в начале было. Сюр с этим рельсами, но мне просто так захотелось и вдохновился, я вот так от 1 произведения, что больше не повторится так/",269933,null],[270267,"2026-10-13T21:03:11",59,"/потом/",270263,null],[270269,"2026-10-13T21:03:47",58,"//спокойной",269933,null],[270270,"2026-10-13T21:04:32",59,"/через час а сейчас задание после спать",270269,null],[270271,"2026-10-13T21:04:39",59,"//но спасибо",270269,null],[270273,"2026-10-13T21:05:14",24,"Поки Ноки/",269933,null],[270355,"2026-10-13T21:29:57",59,"Туша молодого оленя лежит у вас у ног. Кровь ещё не застыла. Мок уже точит нож о камень, другой облизывается, Грызл прикидывает, как делить. Герсон стоит рядом, молот в руке — тяжёлый, липкий.\n\nИ тут кусты за спиной взрываются.\n\nИз леса, ломая ветки, расплёскивая воду с листьев, вылетает олень. Но не такой, как тот. Этот — взрослый. Самец. С рогами. Большой, тяжёлый, с бешеными глазами. Он проносится мимо Писка, чуть не сбивает Мока, тормозит копытами по грязи — и останавливается прямо перед Герсоном. Мёртвый олень — у его ног. Живой олень — над ним.\n\nГрызл хватает камень. Мок — нож. Писк просто замирает.\n\nОлень поднимает голову. И говорит.\n«Стойте! Не бейте! Я — олень из будущего!»\n\nПауза. Мок моргает. Писк открывает рот. Грызл не опускает камень.\n\n«Я пришёл предупредить... самого себя. Прошлого. Вот этого.»\n(он кивает на тушу)\n«Я — это он. Через два года. Я выжил. Я стал вот таким. И я пришёл сказать: не ходи в этот лес. Не подходи к этим гоблинам. Не пей из ручья. И особенно — не доверяй тому, кто говорит складно и держит молот.»\n\nОн переводит дыхание. Смотрит на Герсона. В глазах — трагедия. Настоящая. Оленья.\n«Стойте! Не бейте! Я — олень из будущего!»\n\nПауза. Мок моргает. Писк открывает рот. Грызл не опускает камень.\n\n«Я пришёл предупредить... самого себя. Прошлого. Вот этого.»\n(он кивает на тушу)\n«Я — это он. Через два года. Я выжил. Я стал вот таким. И я пришёл сказать: не ходи в этот лес. Не подходи к этим гоблинам. Не пей из ручья. И особенно — не доверяй тому, кто говорит складно и держит молот.»\n\nОн переводит дыхание. Смотрит на Герсона. В глазах — трагедия. Настоящая. Оленья. Олень поднимает голову в последний раз. Смотрит на тушу. Потом на Герсона. Потом на небо. И говорит — тихо, обречённо, почти шёпотом:\n\n«Эх, опять я опоздал».\n\nОн разворачивается. И убегает. В лес. Ломая ветки, расплёскивая воду, удаляясь всё дальше и дальше, пока не стихает совсем.\n\nТишина.",270263,null],[270358,"2026-10-13T21:30:27",59,"/Это просто шуточная сцена, я решил немного повеселиться и использовал мем из одного видео на YouTube/.",269933,null],[270364,"2026-10-13T21:31:37",24,"*Герсон не понимает ничего*",269933,null],[270367,"2026-10-13T21:33:31",59,"/да не обращай внимания это просто шуточная сцена я использовал мем из ютуба канала *",270364,null],[270369,"2026-10-13T21:33:43",24,"Поки ноки ребят/",269933,null],[270505,"2026-10-14T07:15:13",59,"Лагерь",269933,null],[271613,"2026-10-15T17:59:15",59,"/Дорогие @HKS_Roar_Greninja_dnd и @iakukot, приносим извинения за отсутствие сессии были дела, завтра думаю смогу провести.",269933,null],[271614,"2026-10-15T18:05:20",58,"//понимаю готовься",271613,null],[271627,"2026-10-15T18:35:06",24,"Тут/",269933,null],[271628,"2026-10-15T18:35:12",24,"А оке/",269933,null],[272235,"2026-10-16T17:37:46",59,"@HKS_Roar_Greninja_dnd @iakukot ну я кажись готов а вы?",269933,null],[272246,"2026-10-16T17:42:40",58,"//я готов",272235,null],[272258,"2026-10-16T17:49:38",59,"Первым отвечает гоблинс кривым носом. Он чешет ухо и говорит:\n\n«Ага. Понял. Мы тащим дерево. Ты тащишь дерево. А эти двое...»\n(он тычет в собратьев )\n«...они скрепляют. Частоколами. Всё понял. А что такое частокол?»\n\nГоблин грыз смотрит на свои руки. Потом на него. Потом снова на руки. И говорит медленно:\n\n«У меня два пальца. Как я буду скреплять? Мне надо три».\n\nГо пожимает плечами:\n\n«Я не понял. Кто тащит? Я тащу? Я не тащу. Я вчера тащил. Сегодня очередь Шептуна».\n\nГоблин — бормочет под нос — поднимает голову и говорит: «Духи говорят: дерево нельзя тащить. Дерево само придёт. Если позвать. Я могу позвать. Но не сейчас. Сейчас луна не та.»\n(луны нет, день)\n\n*каждый не очень понял что ты хочешь на крайний случай тебе поясняю вдруг ты подумаешь что у тебя все получилось они по разному восприняли/",270240,null],[272261,"2026-10-16T17:52:20",58,"//в теории можно их запугать?",272258,null],[272270,"2026-10-16T17:55:06",58,"//или это доверие понизит?",272261,null],[272276,"2026-10-16T17:57:32",59,"/ты можете использовать интеллект, чтобы объяснить ситуацию, или запугать и посмотреть, как сработает страх. А можно применить убеждение и убедить человека, используя убеждения *.",269933,null],[272277,"2026-10-16T17:57:50",59,"/Сам думай  ты уверен",272270,null],[272280,"2026-10-16T17:58:45",58,"/r d20+4 михуил пытается придумать как гоблинам все это сделать",269933,null],[272282,"2026-10-16T17:59:34",58,"-в теории ты можешь 1 рукой держать болт и вот так оцепить и когда будет легко забить так то",269933,null],[272283,"2026-10-16T17:59:36",59,"/что за характеристику использовал?",272280,null],[272286,"2026-10-16T18:00:07",58,"//интелект",272283,null],[272287,"2026-10-16T18:00:40",58,"//а он у меня +6 хотя похуй успех итак будет",269933,null],[272290,"2026-10-16T18:06:20",59,"*хочешь описать и огрыгать как командуешь и указывай даёшь?*",272286,null],[272291,"2026-10-16T18:09:25",58,"//ну на написал про молоток и так и дальше помогает михули",272290,null],[272293,"2026-10-16T18:11:21",59,"Работа кипит. Не быстро — но кипит. Гоблины тащат деревья волоком, оставляя за собой мокрые борозды в траве. Кривой Нос идёт боком, потому что так удобнее😁",269933,null],[272295,"2026-10-16T18:12:46",58,"-вы все молодцы теперя у нас есть защита в случаии атаки на нас",269933,null],[272296,"2026-10-16T18:13:56",59,"*И вот, во время работы, прибегает маленький гоблинёнок и сообщает: «О, великий чужак! Там, на восточной стороне ваде, не дают дерево. Ах, злой, злой, злой зветраев».*",269933,null],[272302,"2026-10-16T18:24:25",58,"-ну показывайте где щяс пойдем разберемся \n//изаи был вынужден отойти",272296,null],[272318,"2026-10-16T18:37:36",59,"Лес меняется. Сначала — сосны, сухие, высокие. Потом — берёзы, тонкие, мокрые. Потом — ивы. Низкие, кривые, с ветками, которые свисают до земли и цепляются за плечи. Под ногами — не земля. Что-то мягкое. Пружинистое. Мох. Толстый, как одеяло. Он впитывает воду и не отдаёт.\n\nПахнет. Не лесом. Не грибами. Чем-то кислым. Как будто где-то рядом — старое болото, которое дышит. Медленно. Тяжело. В такт с чем-то, что не видно.",272302,null],[272323,"2026-10-16T18:42:23",58,"-а вы уверены что оно нам угрожает чемто",272318,null],[272325,"2026-10-16T18:43:47",24,"Сорян, вернусь в Воскресенье/",269933,null],[272326,"2026-10-16T18:44:00",59,"*Оглянувшись назад, вы замечаете, что за вами следуют всего лишь двое гоблинов. Они кажутся более или менее смелыми и отвечают вам с глупыми выражениями, говоря: «Эм, ну да. Там злой, злой зверек».*",269933,null],[272337,"2026-10-16T18:47:51",58,"-ладно идемте показывайте где оно и будем защищяться",269933,null],[272347,"2026-10-16T19:06:16",59,"Голубой ты",269933,null],[272348,"2026-10-16T19:07:24",58,"//я не гей",272347,null],[272350,"2026-10-16T19:22:00",59,"/ты не понял это точка голубая или бирюзовая как хочешь ты",272348,null],[272351,"2026-10-16T19:22:38",58,"так ну где вы видели это существо",272350,null],[272352,"2026-10-16T19:24:06",59,"–о да великая чужашк--аа мы возможно, видеть вввооо твм* /1 из гоблинов указывает на деревянную с оружием вгрызанную Громадный зубик/",272351,null],[272353,"2026-10-16T19:24:37",58,"*подхожду чтобы осмотреть его",269933,null],[272354,"2026-10-16T19:25:14",59,"/восприятие",272353,null],[272355,"2026-10-16T19:25:30",59,"/кстати берег является труднопроходимойй местностью вдвое больше скорости требует/",269933,null],[272356,"2026-10-16T19:25:52",58,"/r",269933,null],[272366,"2026-10-16T19:39:46",58,"//на туманый шаг влияет",272355,null],[272368,"2026-10-16T19:39:59",59,"//нет",272366,null],[272369,"2026-10-16T19:40:13",58,"//имба",272368,null],[272370,"2026-10-16T19:41:00",59,"*Зорким глазом орлинным зрением спустя 3 часа наблюдения, что гоблины куда указывали, совершенно правда, ты замечаешь разные следы в болотистой реке, которые говорят о зверьке, которая тиранит местные водные плотины.*",272357,null],[272373,"2026-10-16T19:42:52",58,"*иду по следам",272370,null],[272374,"2026-10-16T19:45:06",59,"*доходя до этой точки местности горничная слышит странные звуки рычания*\n–«Рррр-ффф!»\n· «Грррх…»\n· «Ррр-хррр!» «Шшшш-рррр!»\n· «Фффшшш… рррх!»\n· «Хррр-шшш!»\n\n\n· «Шлёп! — и следом низкое, утробное: „Гррррх…“»\n· «Хвост ударил по воде, а из горла вырвалось злое: „Рррр-фф!“»",269933,null],[272376,"2026-10-16T19:46:36",58,"-так вы все держитесь позади меня пока что и я щяс проверю что там такое\n*проверяю звуки",269933,null],[272380,"2026-10-16T19:50:52",59,"*ты понимаешь что эти звуки с животного происхождения чтобы понять какой именно кидать на природе*",272376,null],[272382,"2026-10-16T19:52:07",58,"/r +4",269933,null],[272391,"2026-10-16T19:58:18",58,"//питомцы чтоль?",269933,null],[272398,"2026-10-16T20:05:25",59,"*Пытаясь вспомнить свои скромные познания о магических животных, горничная-маг обращается к воспоминаниям о детстве и младенчестве. Он осознаёт, что это существо напоминает водное животное, похожее на утконоса или выдру, но точно определить его не может ему больше нравились огненные существа чем водные😂.*",272391,null],[272400,"2026-10-16T20:07:07",58,"-так они хорошие давайте их отнисем себе мб пользы приведут",272398,null],[272410,"2026-10-16T20:10:01",59,"*Вероятно, маленькая горничная не знала, что бобры — территориальные существа. Когда она подошла к бобра, её встретила волна, поднятая гигантским хвостом, который был примерно 1,5 метра в длину. Это был впечатляющий хвост!*",269933,null],[272411,"2026-10-16T20:10:26",59,"Спас лов",269933,null],[272412,"2026-10-16T20:10:35",58,"/r +2",269933,null],[272414,"2026-10-16T20:10:52",58,"//блять а бобры хуть вкусные?",269933,null],[272420,"2026-10-16T20:12:33",59,"*горничная умела уворачивается от волны но забыл что когда она спрыгивает с бревна, которая залезла что на самом деле этот берег все таки болотный речной из за резкого движения спас ловкости чтобы удержаться на скользкой земле* 😂 (советую оценить карту)",269933,null],[272421,"2026-10-16T20:13:02",58,"/r+2",269933,null],[272422,"2026-10-16T20:13:11",58,"/r +2",269933,null],[272425,"2026-10-16T20:13:31",58,"//переплыл море утонул в луже",269933,null],[272427,"2026-10-16T20:15:15",59,"*Поскользнувшись на мокрой земле, он упал лицом в грязь. Ты состояние в ничком твоя скорость становится 0 и так же по тебе преимуществом атакует/",269933,null],[272430,"2026-10-16T20:16:09",58,"//блять",269933,null],[272431,"2026-10-16T20:16:15",59,"/если что требуется потратить половину скорости чтобы стать/",269933,null],[272432,"2026-10-16T20:16:28",59,"Инн",269933,null],[272433,"2026-10-16T20:16:37",58,"/r +2",269933,null],[272435,"2026-10-16T20:16:52",59,"/r борва, курва",269933,null],[272438,"2026-10-16T20:17:20",59,"/ инн\nМаг 16\nБобра курва 14\nГоблин 9",269933,null],[272440,"2026-10-16T20:17:40",58,"//я могу встать и удалить чемнибудь?",269933,null],[272441,"2026-10-16T20:18:02",59,"/да ты половину своей скорости потратишь, ты можешь встать, и у тебя будет бонусные действия и действие. На что",269933,null],[272442,"2026-10-16T20:18:31",58,"/r 4d4+4 стрелы и михуил встает на ноги",269933,null],[272444,"2026-10-16T20:19:28",58,"//можешь отметить нас на карте",269933,null],[272449,"2026-10-16T20:21:02",59,"*резко вынырнув борва курва кусает потрёпанное дерево обрушая на горничную а так вот длиной 15 футов падающую дерево*\n(Спас лов я тебя буду мучить этими спасами😈 или нет )",269933,null],[272451,"2026-10-16T20:21:26",58,"/r +2",269933,null],[272453,"2026-10-16T20:21:36",58,"//еще надо?",269933,null],[272455,"2026-10-16T20:21:44",59,"/если что не обращай внимания не получилось мне попросить этот чат сделать так чтобы они не лежали уже обрушенными он только для меня закрасил места где они не упали/",269933,null],[272456,"2026-10-16T20:21:49",58,"//блять не повезло",269933,null],[272459,"2026-10-16T20:22:23",58,"//а гоблены где?",269933,null],[272462,"2026-10-16T20:23:06",59,"/r 1d6+2 громким хрустом уже потрёпанная изгнившая болотная дерево падает по башке. Бедного горничноe",269933,null],[272464,"2026-10-16T20:23:58",59,"/гоблины смотрят как в вумная великая чужаечка разбирается с великим злобным зверьком ну надо было скомандовать давайте со мной проверять а они то подумали что ты Вумная решила проверить и разобраться/",272459,null],[272465,"2026-10-16T20:24:33",59,"*но видимо черепушка горничная оказалась крепкая что или дерево оказалось хрупкое гнилой что получил по башке шишку и опилки при этом не придавлено*",269933,null],[272467,"2026-10-16T20:24:39",59,"/ ход @iakukot",269933,null],[272469,"2026-10-16T20:25:24",58,"//оно ближе чем 15 футов ко мне?",269933,null],[272474,"2026-10-16T20:26:05",58,"/r 3d6",269933,null],[272477,"2026-10-16T20:26:18",58,"//твоя очередь делать спас ловкости",269933,null],[272479,"2026-10-16T20:26:50",59,"/r d20 ты зналa что курва бобра ловкая она управляет реальностью и выбивает себе чистые двадцатки",269933,null],[272481,"2026-10-16T20:27:14",58,"//не вижу",272480,null],[272485,"2026-10-16T20:28:53",59,"/да кстати хочу заранее извиниться если как то скомкано и скучно получается идея если честно была хорошая но плохо отыгрываю может надо было больше времени подумать ну не было этой возможности но надо было провести пару часов приехавшие в гости племянницы*",269933,null],[272486,"2026-10-16T20:29:51",58,"//та и так пойдет в принципи",269933,null],[272488,"2026-10-16T20:30:29",59,"*борова курва не смогла увернуться от дыхания неожиданно огнедышащий горничной получившая опалены  зложно шипит*",269933,null],[272489,"2026-10-16T20:30:44",59,"/все или еще что-то?",269933,null],[272491,"2026-10-16T20:31:07",58,"-вы желание имете мне помочь?",269933,null],[272493,"2026-10-16T20:32:42",58,"-если нет то тогда смотроите и учитесь",272491,null],[272495,"2026-10-16T20:33:16",59,"–о у меня великая чужираачка ты крхпутя, мы п..ом.очь *но показав глупая выражение лица* /гоблина побежала но споткнулась упав в воду надо было уточнять приказы это напарники юниты которые требуют чётких указаний или они делают глупые ошибки/",272491,null],[272497,"2026-10-16T20:34:27",58,"//понятно а им надо инициатива всеже они уже в бою",269933,null],[272498,"2026-10-16T20:35:38",59,"/В твоей власти, если ты сможешь командовать, ты можешь бонусные действия потратить, чтобы приказать. Некоторые моменты требуют проверки харизмы или других проверок, каким образом ты это говоришь, а некоторые можно вообще не требовать, если приказ достаточно легко понятен и и сложно испоганить/",272497,null],[272499,"2026-10-16T20:36:16",58,"//ну полетели тогда мне или тебе инт куидать?",269933,null],[272500,"2026-10-16T20:36:20",59,"/r +2 одна наступившая единица гоблинская в бой и  болтыхается в воде а другая стоит и наблюдает",269933,null],[272502,"2026-10-16T20:37:08",58,"//ну теперь очередь бобра",269933,null],[272503,"2026-10-16T20:37:18",59,"/ничего не будешь делать бонусской?",269933,null],[272504,"2026-10-16T20:37:49",58,"//не пока что",272503,null],[272507,"2026-10-16T20:39:06",59,"/r злая борва курва улетает в воду * не нравится будет подпаленной* затаиваясь и слышится хряк хряк хряк",269933,null],[272510,"2026-10-16T20:39:56",59,"*но но бурва курва слишком увесистая и большая, что не получается ей обмануть горничную которая понимает звуки что это что то грызёт и прекрасно видит её тень в воде.*",269933,null],[272511,"2026-10-16T20:40:57",58,"//мой ход теперь?",269933,null],[272525,"2026-10-16T21:01:00",58,"/r 4d4+4 стрелы",269933,null],[272527,"2026-10-16T21:01:27",58,"-так смотри ты встань прям передомною понял",269933,null],[273522,"2026-10-17T20:14:00",59,"*Бобёр с недовольным видом выглядывает из воды, его красные глаза смотрят прямо в душу, Затем бобёр резко ударяет по воде, и вы отталкиваете в сторону свою крепость и начинает грызть плотину вызывай вообще поток воды который устремился наружу.\n\n/ @iakukot спас сила сл 12 если пропал ты падаешь ночком и уносишь потоком на 30 футов назад/",269933,null],[273524,"2026-10-17T20:14:25",59,"/r d20-1 первый гоблин пытается удержаться от резкого удара воды",269933,null],[273529,"2026-10-17T20:14:53",59,"/r d20-1  второй гоблин пытается удержаться от резкого удара воды",269933,null],[273582,"2026-10-17T20:56:52",58,"//так я тут",269933,null],[273583,"2026-10-17T20:56:56",58,"/r",269933,null],[273587,"2026-10-17T20:57:22",58,"//удача",273586,null],[273589,"2026-10-17T20:57:38",58,"//хотя щяс посчитаю секунду",269933,null],[273590,"2026-10-17T20:58:04",58,"//да был еще 1 везунчик",269933,null],[273593,"2026-10-17T20:59:32",59,"*Мощная волна сносит 1 неудачливого гоблина назад, а горничная и 2 гоблин устойчиво держатся на земле, противостоя сильному потоку воды, всего лишь отступая на 8 футов назад, чтобы удержать равновесие.*",269933,null],[273595,"2026-10-17T21:04:08",58,"//на карте отметишь нас?",269933,null],[273597,"2026-10-17T21:06:57",59,"*после резкое волны бобёр бесследно пропал*",269933,null],[273600,"2026-10-17T21:15:26",59,"/ @iakukot короче у бобра очень мало осталось оказывается хп еле как он выжил после стрелы твоей теперь бойся оглядывайся и береги свою жопу*",269933,null],[273602,"2026-10-17T21:22:21",59,"/хорошо что я решил пересчитать хп а то бобёр бы умер рано а он должен тиранить вас*",269933,null],[273603,"2026-10-17T21:38:43",58,"-так идите за мной будьте осторожны мы должны ее найти \n//меня тут отвлекают чуток",269933,null],[273604,"2026-10-17T21:40:51",59,"/ С помехой восприятия чтобы найти следы",269933,null],[273605,"2026-10-17T21:41:07",59,"/Все таки поток воды большинство следов замёл ещё он в воде передвигается",269933,null],[273606,"2026-10-17T21:41:34",58,"//ммм еще и везунчиков больше нету",269933,null],[273607,"2026-10-17T21:41:42",58,"/r -d20",269933,null],[273609,"2026-10-17T21:44:38",59,"*Горничная осознаёт, что опасность для ее жопый всё ещё остаётся реальной, и её проницательности не хватает, чтобы найти следы на воде и отследить их.*",273607,null],[273610,"2026-10-17T21:45:34",58,"//мммм\n-так будьте осторожны оно гдето рядом",269933,null],[273611,"2026-10-17T21:45:50",58,"*иду прямо к плотине",269933,null],[273613,"2026-10-17T21:54:27",59,"*подходя горничная к плотине видит порванную стенку плотины*",269933,null],[273614,"2026-10-17T21:55:24",58,"//анализ можно кинуть?",269933,null],[273619,"2026-10-17T22:15:32",58,"/r d20+6",269933,null],[273625,"2026-10-17T22:20:22",59,"*горничная понимает что эта умено сделанная плотина является жилищем и так же коварной ловушкой помогающей скрыться для своего хозяина если правильно перегрызть опирающие балки*",269933,null],[273642,"2026-10-17T22:55:06",58,"-так ну тут банальная ловушка так что давайте сожем ее",269933,null],[273643,"2026-10-17T22:55:25",58,"/r d20+6 \n/r d10",269933,null],[273646,"2026-10-17T23:07:18",58,"//посоле этого мастер ушел в дипресию",269933,null],[273648,"2026-10-17T23:09:49",59,"/да нет бобры ищут те упорный работяги/",273646,null],[273649,"2026-10-17T23:10:17",59,"/была такая история как 1 правительство 1 страны сносила дамбы и плотины этих Бобров они за ночь обратно все строили это была долгая борьба я только не помню как она закончилась/",269933,null],[273650,"2026-10-17T23:13:58",58,"//хм так доамба сгорела или у меня бобер флеш?",273649,null],[273651,"2026-10-17T23:14:27",59,"/ну кто знает кто знает может вода слишком глубокая",273650,null],[273652,"2026-10-17T23:14:36",59,"/или он очень быстро плавится",269933,null],[273653,"2026-10-17T23:15:09",58,"//разве мастер это не всезнающие существо?",273651,null],[273654,"2026-10-17T23:21:42",59,"/это для тебя предположение накидывает",273653,null],[273655,"2026-10-17T23:22:23",59,"/это же ты не смог найти куда он сьебался",269933,null],[273656,"2026-10-17T23:23:17",58,"//хм ладно завтра продолжим уже во всем сборе а то щяс как то не идет у меня",269933,null],[274515,"2026-10-18T17:03:10",24,"Чуть позже приду/",269933,null],[274533,"2026-10-18T17:23:47",58,"//буду ждать",274515,null],[274545,"2026-10-18T17:40:12",24,"Тут/",269933,null],[274546,"2026-10-18T17:57:03",59,"*ты прибил олени и стоишь над его трупом, что будешь делать?*",274545,null],[274547,"2026-10-18T17:57:13",59,"*а ты сжёг плотину*",274533,null],[274549,"2026-10-18T18:06:23",59,"*ладно скажите когда будете готовы*",269933,null],[274562,"2026-10-18T18:19:52",24,"-Несем его друзья мои\n\n*Взял труп оленя и ждет пока остальные озьмут*",269933,null],[274563,"2026-10-18T18:23:27",59,"*потратив больше времени черепашка вместе с гоблинами несут труп*",274562,null],[274566,"2026-10-18T18:35:39",58,"-так ты гоблин щяс наблюдай за фокусом \n*использую призыв фамилиара и призываю сову и посылаю ее проверить что там",274547,null],[274568,"2026-10-18T18:38:40",59,"*ты все попытки поймать бобра не оставишь, да?",274566,null],[274569,"2026-10-18T18:38:59",58,"//да",274568,null],[274572,"2026-10-18T18:41:22",59,"*ну, восприятие надеюсь, ты не забыл у сова модификатор.*",274569,null],[274574,"2026-10-18T18:42:08",58,"/r d20+3 скрытность \n/r d20+3 восприятие",269933,null],[274576,"2026-10-18T18:42:18",58,"//f",269933,null],[274577,"2026-10-18T18:43:40",59,"*ты  понимаешь, что сова не очень хороший разведчик, чтобы использовать её в качестве ночного охотника в такой  промежуток времени.*",269933,null],[274579,"2026-10-18T18:45:00",58,"//ладно с совой не прокатило пойду сам тогда",269933,null],[274580,"2026-10-18T18:46:15",58,"//а я могу отхилится?",269933,null],[274581,"2026-10-18T18:46:30",59,"/короткий отдых или заклинание хила",269933,null],[274582,"2026-10-18T18:46:51",59,"/ну или вообще продолжительный отдых",269933,null],[274583,"2026-10-18T18:47:42",58,"//давай короткий отдых и какую кость кидать?",269933,null],[274585,"2026-10-18T18:48:25",59,"/у тебя на твоём 4 уровне 1к6 хитов их у тебя 4. Значит 4к6 ну, ты можешь выбрать, сколько ты хочешь потратить",269933,null],[274586,"2026-10-18T18:48:41",58,"/r 2d6",269933,null],[274588,"2026-10-18T18:48:46",59,"/ну не забывай что ты час потратишь чтобы отдохнуть",269933,null],[274589,"2026-10-18T18:48:52",58,"//фулл хп снова",269933,null],[274590,"2026-10-18T18:48:56",58,"//знаю",274588,null],[274592,"2026-10-18T18:49:42",58,"//А еще и ячейку второго уровня кдшу или это уже в другой отдых пойдет?",269933,null],[274593,"2026-10-18T18:50:17",59,"*доходя, до племени ты замечаешь перемены гоблиный начали суетиться возле ворот*",274562,null],[274594,"2026-10-18T18:50:33",24,"-Что такое ребят?",269933,null],[274595,"2026-10-18T18:51:20",59,"/продолжительный отдых",274592,null],[274596,"2026-10-18T18:51:34",58,"//займешься посилением пока я с бобром доразберусь?",269933,null],[274597,"2026-10-18T18:51:42",58,"//а тогда не надо",274595,null],[274598,"2026-10-18T18:52:25",59,"–о великий чужак пришёл с добычей!\n–мы по велению другой великой чужачки строим неки \"чистокол\"",274594,null],[274599,"2026-10-18T18:55:17",58,"//мне час реального времени ждать или щяс уже ок?",274588,null],[274600,"2026-10-18T18:55:43",59,"/уже все прошёл",274599,null],[274601,"2026-10-18T18:56:03",58,"- так гоблены ну пошлите за бобром?",269933,null],[274602,"2026-10-18T18:56:24",58,"- и разгромим мы его и пустим на дома нам",269933,null],[274603,"2026-10-18T18:56:34",59,"–о, великая чужачк, вы охотница? 😻",274601,null],[274604,"2026-10-18T18:56:54",58,"/r d20+1 выступление",269933,null],[274606,"2026-10-18T18:57:02",58,"-ну стать надо",274603,null],[274607,"2026-10-18T18:57:15",58,"//вдохновляю их пойти со мною",274604,null],[274608,"2026-10-18T18:57:51",59,"–о, великая чужачка! Мы Гука вагу вумные гоблины последуем за тобой, чтобы учиться!!!!",269933,null],[274609,"2026-10-18T18:58:27",58,"*иду с ними в этот тунель искать бобрятину",269933,null],[274610,"2026-10-18T18:58:38",59,"*какой туннель*",274609,null],[274611,"2026-10-18T18:58:44",24,"-Не называйте меня великим друзья. Звать меня Герсон Бум. Но если так хотите звите меня Чужак Бум",274598,null],[274612,"2026-10-18T18:59:04",58,"//тогда по следам бобра",274610,null],[274613,"2026-10-18T18:59:21",59,"–о, хорошо чужак бум! Ты дашь нам мясо я очень голодный у меня взрывается жежтве",274611,null],[274614,"2026-10-18T18:59:53",59,"*Какие следы ты нашёл-то в воде? Ты хочешь вплавь отправиться за ним, особо не понимая следы в воде?*",274612,null],[274615,"2026-10-18T18:59:54",24,"-Подождите всех! Устроим пир в честь нашего прибытия!",269933,null],[274616,"2026-10-18T18:59:57",58,"//вот так вот быть 12 леткой путают с девушкой все время...",274608,null],[274617,"2026-10-18T19:00:13",59,"/ну, ты сам виноват, что ты в горничную одет/",274616,null],[274618,"2026-10-18T19:00:15",58,"//а оно уплыло?",274614,null],[274619,"2026-10-18T19:00:25",24,"Нет/",274616,null],[274620,"2026-10-18T19:00:34",24,"По своему давнему опыту, нет/",269933,null],[274621,"2026-10-18T19:00:37",59,"*ну как знать, может, уплыла, может, поблизости ты этого не знаешь Ты же в воде не втык-тык! Чтобы разобрать*",274618,null],[274622,"2026-10-18T19:00:51",58,"//я по своему давнему опыту скажу что меня путали",274620,null],[274623,"2026-10-18T19:01:24",24,"Окак/",269933,null],[274624,"2026-10-18T19:03:12",58,"-так у вас есть идеи где его искать?",274621,null],[274625,"2026-10-18T19:09:59",59,"–о, вумная чужаечка, мы гугу гага знать как поймать опасного зверька",274624,null],[274626,"2026-10-18T19:10:57",58,"-расказывай",269933,null],[274627,"2026-10-18T19:12:28",59,"–мммы, брать в руки червячков совать руки в водеда и поймать очень, очень, очень опасную звереншку",274626,null],[274628,"2026-10-18T19:13:26",58,"-хм звучит интересно ну давайте попробуем",269933,null],[274632,"2026-10-18T19:16:49",59,"/ты вместе с ними хочешь попробовать?/",274628,null],[274634,"2026-10-18T19:18:00",58,"//я наблюдаю и стою на готове",274632,null],[274637,"2026-10-18T19:19:13",59,"*Вы наблюдаете, как два гоблина потратили почти полчаса, чтобы выкопать нескольких разных червей. Они засовывают их в воду своими грязными руками, и спустя много часов ловят несколько маленьких рыбок.*",274634,null],[274644,"2026-10-18T19:23:37",58,"-хм ну теперь еда у нас есть за то ладно оставим бобра тогда времено",269933,null],[274648,"2026-10-18T19:24:41",58,"-извиняюсь что вас подвел",269933,null],[274651,"2026-10-18T19:25:58",59,"*на тебя восхищённо смотрят*\n–о великая, вумная чужачка, ты крутая ты прогнала злого злого опасного зверя",269933,null],[274652,"2026-10-18T19:26:07",59,"–теперь у нас есть доступ к этому месту.",269933,null],[274653,"2026-10-18T19:26:22",58,"//оптимисты",269933,null],[274654,"2026-10-18T19:27:03",58,"-ну кстати да теперь мы спокойно сможем рамширитьсч если захотим а теперь пошлите домой а то нам дома строить еще",269933,null],[274658,"2026-10-18T19:29:33",59,"*Ты возвращаешься назад, осознавая, что потратил впустую огромное количество времени. Уже вечереет, а гоблины завершили лишь малую часть своей работы.*",274654,null],[274669,"2026-10-18T19:36:36",59,"/я как понимаю вы хотите просто ждать ничего не делая @iakukot @HKS_Roar_Greninja_dnd ? Просто наблюдать за работой./",269933,null],[274673,"2026-10-18T19:38:15",24,"*Герсон наблюдает за работой*",274669,null],[274692,"2026-10-18T19:46:30",58,"//ага",274669,null],[274713,"2026-10-18T20:01:16",59,"*Потратив время, вы смотрите, как гоблин неумело выполняют приказы, которые были давно отданы великой чужачкой-горничной.*",269933,null],[274716,"2026-10-18T20:01:54",58,"-что то не так?",269933,null],[274719,"2026-10-18T20:05:41",59,"– Вумная чужачка, эти бестолочь не понимают меня великого, жуй что надо соплями прикреплять эти шняки шняги",274716,null],[274729,"2026-10-18T20:10:59",58,"-хм давай я посмотрю как ты им даешь команды",274719,null],[274738,"2026-10-18T20:14:10",59,"*Жуй – тот самый, с кривым носом — выпячивает грудь. Он явно очень старается выглядеть вождём. Смотрит на своих.*",269933,null],[274740,"2026-10-18T20:14:50",59,"«Так! —* орёт Жуй\". — Вумная чужачка сказала: я команды даю! Значит, я — главный! Слушай меня!»",269933,null],[274741,"2026-10-18T20:15:35",59,"«Ты! Мелкисий! Хватавай эту... эту... шнягу! И прикретьепляй!»\n«Куда прикр...еплять?» — спрашивает гоблин.\n«Туда! К той! К другой шняге!»\n«А чсем?»",269933,null],[274742,"2026-10-18T20:16:02",58,"-ну теперь понятно почему работа плохо идет",269933,null],[274744,"2026-10-18T20:16:16",58,"-Ты хотябы пример им покажи",269933,null],[274745,"2026-10-18T20:16:51",59,"*Жуй задумывается. На лице — работа мысли. Тяжёлая. Потом лицо светлеет*:\n«Соплчяями!  что надо и прикрпврепляй! Слюни — это клей! Я так в месслкий делал! Держит — не оторвмяёшь!»",269933,null],[274746,"2026-10-18T20:16:55",58,"//интересно эта таблица обновитсч когданибудь?",270156,null],[274748,"2026-10-18T20:18:27",58,"-уверен что нужен клей тут?",274745,null],[274750,"2026-10-18T20:18:39",59,"Он скрещивает руки на груди и стоит. Довольный. Как будто только что решил сложнейшую задачу.",274745,null],[274752,"2026-10-18T20:20:06",58,"-давай теперь я попопробую а ты сделай учет над ошибками",274750,null],[274753,"2026-10-18T20:20:41",58,"//надо кости кидать?",269933,null],[274755,"2026-10-18T20:21:20",59,"/насчёт этого пока что рано говорить максимум, что скажу, что притащенная тушка олянья добавила в шкале еда только меньше половины к 2 единице.\nА шкала жиличия только в прогрессе.",270156,null],[274758,"2026-10-18T20:23:24",58,"//понятно",274755,null],[274786,"2026-10-18T20:53:07",59,"*давай твори теперь тебе надо это отыграть просто кинуть уже не хватит*",274752,null],[274831,"2026-10-18T21:18:03",58,"//так ну  \n-смотри иди сюда бери ставь деревяшку вот так теперь возьми молоток \n*тянется к другой дощечки и начинает забивать \n-теперь бери частокол и забивай его между деревяшками \n*нашинает забиаать \n-теперь вот так вот надо будет сделать вокруг всего забивать надо прочно и надежно",269933,null],[275522,"2026-10-19T17:01:48",59,"/ @iakukot @HKS_Roar_Greninja_dnd вопрос /",269933,null],[275525,"2026-10-19T17:02:23",24,"Тут/",269933,null],[275527,"2026-10-19T17:02:46",59,"/вопрос к вам готовы выслушать/",269933,null],[275531,"2026-10-19T17:04:34",24,"Какой?/",269933,null],[275574,"2026-10-19T17:15:00",59,"/Я, короче, покумекал, и у меня такой вопросик образовался: вы готовы к так называемому мини-компании?  готовый , конечно, вас долго водить не буду по прикидкам пару недель или максимум месяц либо от вашей активности  /",269933,null],[275576,"2026-10-19T17:15:22",24,"Оке/",269933,null],[275578,"2026-10-19T17:16:25",59,"/и вот у вас есть намерение до конца пройти?/",269933,null],[275582,"2026-10-19T17:16:49",24,"Конечно/",269933,null],[275595,"2026-10-19T17:19:44",59,"/Учитывая, что не каждый день будет таким насыщенным, по моей логике не является ГГ, который притягивает неприятности для племени, просто я прикинул еще одну или, возможно, двух игроков присоединиться дать возможность, чтобы вам было полегче в поздних арках, конечно, в начальных арках не настолько всё сложно./",269933,null],[275672,"2026-10-19T17:47:32",58,"//хм ну я не против чтобы это был кампеин давненько хотел взять на себя кампеин какойнибудь",269933,null],[275692,"2026-10-19T17:59:47",59,"/ну так же вы можете двое погнать или ещё кого-то, если думаете, справитесь С поздними арками/",275672,null],[275698,"2026-10-19T18:03:57",59,"/ну, если вы не против или не уверены в своих силах я могу организовать донабор/.",269933,null],[275701,"2026-10-19T18:05:02",24,"Не против/",269933,null],[275705,"2026-10-19T18:19:18",58,"//мне безразницы",269933,null],[275721,"2026-10-19T19:28:23",59,"/ @HKS_Roar_Greninja_dnd  @iakukot можно немножко позже начну и не так много времени будет проводить дела есть и немножко голова побаливает. ну, сегодня точно будет. постараюсь хоть чутка./",269933,null],[275722,"2026-10-19T19:29:29",58,"//оке",275721,null],[275723,"2026-10-19T19:29:42",24,"//оке",269933,null],[275778,"2026-10-19T20:32:36",59,"*Гоблин с очень большим восхищением и наблюдением слушать и недоумением от слишком заумных слов и многосложностей но принимается по указаниям работать что достаточно потребует ещё с завтрашнего дня.*",274831,null],[275794,"2026-10-19T20:39:23",59,"*К тому времени, как работа была выполнена примерно наполовину, уже начало темнеть. Гоблины забегали, чтобы развести костры и принести всё необходимое или нет.*",269933,null],[275799,"2026-10-19T20:42:17",58,"//тэк",269933,null],[275801,"2026-10-19T20:43:12",58,"-хорошоя работа на седня теперь нам надо обсудить горнизон",269933,null],[275803,"2026-10-19T20:43:58",58,"-3 гоблена должны будут охранять местность и не жать друг дркгу уснуть и в случаии опасности сразу будить нас",269933,null],[275804,"2026-10-19T20:44:24",58,"-есть добровольцы?",269933,null],[275805,"2026-10-19T20:44:50",59,"*лес рук*",275804,null],[275806,"2026-10-19T20:45:10",58,"//как в школе или прям лес?",275805,null],[275807,"2026-10-19T20:45:22",59,"/1 вариант*",269933,null],[275808,"2026-10-19T20:45:49",58,"//хм кости могут помочь?",269933,null],[275810,"2026-10-19T20:46:44",58,"-ладно тогда я первым останусь а потом разбужу 3 когото на стражу понятно?",269933,null],[275811,"2026-10-19T20:47:18",59,"*большинство гоблинов кивнуло и начала подбегать к кострам и начинать подготовку*",269933,null],[275812,"2026-10-19T20:47:58",58,"*встаю и осматриваю местность думая почему дьявол нас сюда послал",269933,null],[275815,"2026-10-19T20:49:35",58,"*попутно решаю заготовить заклинание прызыв фамилиара",275812,null],[275822,"2026-10-19T20:54:10",59,"*гоблины что-то подкрикливают и начинают танцы у костра и попутно подкидывая котёл всякое.*",269933,null],[275826,"2026-10-19T20:55:01",58,"*подхожу к ним\n-это у вас ритуал какойто?",275823,null],[275829,"2026-10-19T20:57:32",59,"*1 гоблин танцуя горлач на гоблинском*–вумная чужатстсчка, у нас праздностсовиик, наше пчбатслемя чугуннский тепечтосрь под защистситой великчоих велаоиких посланнрвтаиков",275826,null],[275830,"2026-10-19T20:57:36",58,"//мне не нравится реакция которую пихнули",275823,null],[275832,"2026-10-19T20:58:08",58,"//великих ага ага",275829,null],[275833,"2026-10-19T20:58:29",24,"Тут/",269933,null],[275834,"2026-10-19T20:58:45",58,"-хм интересный ритуал ладно я тогда дальше охронять местность",275829,null],[275835,"2026-10-19T21:00:32",58,"//кароч видешь ту фотку котла так вот тебя там жарят",275833,null],[275836,"2026-10-19T21:00:59",24,"Та ебаный рот/",269933,null],[275837,"2026-10-19T21:01:36",58,"//больше еды надо было принести",275836,null],[275838,"2026-10-19T21:01:52",24,"Не вижу сообщения что меня жарят/",269933,null],[275839,"2026-10-19T21:02:42",24,"Если это была шутка тогда не смешно/",269933,null],[275840,"2026-10-19T21:02:59",58,"//кому как",275839,null],[275843,"2026-10-19T21:05:09",59,"/они после трудного дня готовят еду и они всякое кидают что там нарисовано на картинке это не означает что это было кинуто/",275838,null],[275846,"2026-10-19T21:09:13",59,"*гоблины вдоволь повеселившись принялись кушать варево*",269933,null],[275847,"2026-10-19T21:09:32",59,"*несколько гоблинов набрав в разные ёмкость приносит вам варево*",269933,null],[275848,"2026-10-19T21:09:39",58,"//я надеюсь у нас щяс не появится стата голода",269933,null],[275849,"2026-10-19T21:09:52",59,"/появится появится не так все легко",275848,null],[275850,"2026-10-19T21:10:12",58,"//а сна?",269933,null],[275851,"2026-10-19T21:10:42",59,"/тоже",269933,null],[275852,"2026-10-19T21:10:53",59,"/ты что робот",269933,null],[275853,"2026-10-19T21:11:00",58,"Да//",275852,null],[275854,"2026-10-19T21:11:00",59,"/чтобы обходиться без этого",269933,null],[275856,"2026-10-19T21:11:08",59,"/не п**** мне",275853,null],[275857,"2026-10-19T21:11:33",58,"//я лючше я студент еда и сон мне не нужны",269933,null],[275860,"2026-10-19T21:12:22",59,"/я тоже студент и давай не забывай что это не очень хорошо сказывается на организм",275857,null],[275861,"2026-10-19T21:12:57",59,"/и у тебя в этом мире где ты найдёшь какао бобы чтобы сделать кофе или на чем там выживают обычные такие студенты я не знаю я кофе вообще не люблю",269933,null],[275862,"2026-10-19T21:14:59",58,"//я нп батончиках живу но мы что то отошли от квеста \n-сбасибо больше \n*михуил оглядывает что ему дали",269933,null],[275863,"2026-10-19T21:15:54",59,"*тебе крайне интересную ёмкость дали немножко треснувшая глиняная посуда познавшие времена и жидкостью внутри прозрачность синеватые*",275862,null],[275864,"2026-10-19T21:16:27",59,"*от которого пахнет достаточно нейтрально но при этом пряности*",269933,null],[275865,"2026-10-19T21:16:48",58,"*пробую",269933,null],[275866,"2026-10-19T21:18:20",59,"*Вы наслаждаетесь вкусом, но вам кажется, что чего-то не хватает. Конечно, ваш персонаж вряд ли часто пробовал такие изысканные блюда ну в целом для непризорника которая всякое поела сносно на вкус .*",269933,null],[275867,"2026-10-19T21:21:24",58,"//я могу кинуть интелект чтобы предположить зачем дьявол нас послал сюда?",269933,null],[275868,"2026-10-19T21:23:49",59,"*я бы сказал здесь больше мудрость, потому что ты делаешь диктуцию ну я бы сказал здесь больше помеха потому что у тебя информации для дедуции достаточно мало да и это может быть ложным в этом даже на основе догадок которые у тебя от действий демона*",275867,null],[275869,"2026-10-19T21:25:33",58,"//тобишь мудрость кидать",275868,null],[275870,"2026-10-19T21:25:45",58,"//а везунчик уже откдшился :3?",269933,null],[275871,"2026-10-19T21:26:01",59,"*ага, проницательность с помехой для возможности сделать дедукцию*",269933,null],[275872,"2026-10-19T21:26:19",59,"/сначала тебе нужно продолжить Отдых ты короткий же делала",275870,null],[275873,"2026-10-19T21:27:48",58,"/r -d20+2",269933,null],[275875,"2026-10-19T21:28:48",58,"//мда не судьба",275874,null],[275877,"2026-10-19T21:29:45",59,"*ты понимаешь взрывая мысли своей в голове дедукцией что демон просто ленивый начальника которая решила скинуть проблемы на почти бесплатная отрабочих*",269933,null],[275878,"2026-10-19T21:31:03",58,"//ммм сколько новой инфы \n*решаю опереться на недостроеную стену и отдыхаю ждя чегото",275877,null],[275879,"2026-10-19T21:32:43",59,"/ @HKS_Roar_Greninja_dnd может ты что то хочешь",269933,null],[275880,"2026-10-19T21:33:31",24,"*Герсон сидит и спокойно ест. Он уже хочет умиротворения. Его все устраивает*",269933,null],[275881,"2026-10-19T21:34:09",59,"/ну тогда завтра определим что возможно случится может и ничего не случится а я сейчас хочу поспать завтра сложный день гребаное мероприятие*",269933,null],[275882,"2026-10-19T21:34:22",59,"/всем спокойней/",269933,null],[275883,"2026-10-19T21:35:13",58,"//спокойной",269933,null],[275885,"2026-10-19T21:35:40",24,"Оке/",269933,null],[278352,"2026-10-21T20:13:30",59,"/Что ж поприветствуем пополнение/",269933,null],[278353,"2026-10-21T20:15:16",59,"*В ярких лучах алого света, который исходил из центрального костра, появляются фигуры и гнусный розовый туман с знакомым изображением скелета ЛИ 18.*\n@M1DNiGhT123 @Ke_te_de",269933,null],[278354,"2026-10-21T20:20:53",24,"Тут/",269933,null],[278357,"2026-10-21T20:36:11",58,"//тути",269933,null],[278358,"2026-10-21T20:36:39",13,"/здесь",269933,null],[278360,"2026-10-21T20:45:51",59,"*из тумана выходят 2 фигуры 1 человек другой ящерлюд гоблины восторженно кричат*",269933,null],[278361,"2026-10-21T20:51:54",59,"/ну дальше вы можете социалить действовать/",269933,null],[278363,"2026-10-21T20:53:39",13,"Людоящер немного в удивление от такого появляения и смены обстановки но всё же придя в себя кланяется и представляется\n\n— я Арит, лесной странник по совместительству охотник",269933,null],[278364,"2026-10-21T20:54:12",58,"*михуил смотрит на него и спрашивает \n-вы враги или как?",278363,null],[278365,"2026-10-21T20:54:27",13,"— мы по заданию",269933,null],[278366,"2026-10-21T20:54:44",58,"-тоже от дьявола глазастика?",278365,null],[278367,"2026-10-21T20:55:24",13,"— вроде как",269933,null],[278368,"2026-10-21T20:55:45",58,"-Понятно",269933,null],[278369,"2026-10-21T20:55:56",58,"-Голодные?",269933,null],[278370,"2026-10-21T20:56:13",13,"— ну поесть было бы неплохо в любой ситуации",269933,null],[278371,"2026-10-21T20:56:27",13,"— никогда не знаешь когда повезет на охоте, а когда нет",269933,null],[278372,"2026-10-21T20:56:41",58,"-тогда подойдите к тем гоблинам и попросите у них еды мб дадут",269933,null],[278373,"2026-10-21T20:58:34",58,"-работать на благо деревни готовы?",269933,null],[278374,"2026-10-21T20:58:43",13,"— конечно",269933,null],[278375,"2026-10-21T20:59:14",58,"-ты же охотник да? Тогда будет добыдчиком еды",269933,null],[278376,"2026-10-21T20:59:25",13,"— как скажешь",269933,null]]);
